<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\SchoolClass; use App\Models\Teacher; use Illuminate\Http\Request;
class SchoolClassController extends Controller { public function index(){return view('admin.classes.index',['classes'=>SchoolClass::with('homeroomTeacher.user')->orderBy('grade_level')->orderBy('name')->paginate(15)]);} public function create(){$teachers=Teacher::with('user')->get();return view('admin.classes.create',compact('teachers'));} public function store(Request $request){$v=$request->validate(['name'=>'required|string|max:50','grade_level'=>'required|integer|in:10,11,12','homeroom_teacher_id'=>'nullable|exists:teachers,nip','academic_year'=>'required|string|max:9']);SchoolClass::create($v);return redirect()->route('admin.classes.index')->with('success','Kelas berhasil ditambahkan.');} public function edit(SchoolClass $class){$teachers=Teacher::with('user')->get();return view('admin.classes.edit',['schoolClass'=>$class,'teachers'=>$teachers]);} public function update(Request $request,SchoolClass $class){$v=$request->validate(['name'=>'required|string|max:50','grade_level'=>'required|integer|in:10,11,12','homeroom_teacher_id'=>'nullable|exists:teachers,nip','academic_year'=>'required|string|max:9']);$class->update($v);return redirect()->route('admin.classes.index')->with('success','Kelas berhasil diperbarui.');} public function destroy(SchoolClass $class){$class->delete();return redirect()->route('admin.classes.index')->with('success','Kelas berhasil dihapus.');} }
